-- More quest completion texts (quest_offer_reward) and progress texts (quest_request_items) that our world lacked, word for
-- word as players' games showed them, after 2026_11_11_10.
-- Data from Efficient Games (https://efficient.games), licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/).
-- Source: EG Link output, github.com/JIVESCORP/eg-link-output-wowf commit 9fcae73c (data to 2026-11-10), texts.enUS.json,
-- newest live build first (70862, 70840, 70790, older live builds, then the Forever beta), the variant most players saw.
-- Changed: line breaks written as $B, rows written as TrinityCore rows. Only quests with no row here, or with the
-- placeholder row of 2026_11_08_20 (VerifiedBuild -1), get one; a real existing text is never replaced.
-- VerifiedBuild = the build the text was seen on. Safe to run again.

-- 1) completion texts (94 quests; 2 of them replace a placeholder: 92819, 98248)
DELETE FROM `quest_offer_reward` WHERE `VerifiedBuild`=-1 AND `ID` IN (92819,98248);
ON DUPLICATE KEY UPDATE `ID`=`ID`;

-- 2) progress texts (103 quests)
ON DUPLICATE KEY UPDATE `ID`=`ID`;
